RU = dict(PAIRS)
EN = {ru: en for en, ru in PAIRS}


def tr(text, language="ru"):
    return RU.get(text, text) if language == "ru" else text


def translate_message(text, language="ru"):
    table = RU if language == "ru" else EN
    text = str(text)
    if text in table:
        return table[text]
    # Short UI labels must not rewrite a directory such as C:/Workspace.
    phrases = [key for key in table if len(key) >= 20 or key.endswith(": ")]
    pattern = "|".join(re.escape(key) for key in sorted(phrases, key=len, reverse=True))
    return re.sub(pattern, lambda match: table[match.group()], text)
